 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = {}
    for row in grid:
        for v in row:
            freq[v] = freq.get(v, 0) + 1
    background = max(freq, key=freq.get)

    # Only uniform lines in a non-background color are panel dividers.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background]
    sep_colors = {grid[r][0] for r in sep_rows} | {grid[0][c] for c in sep_cols}

    def spans(size, separators):
        bounds = [-1] + separators + [size]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)
    panels = []
    for ri, (r0, r1) in enumerate(row_spans):
        for ci, (c0, c1) in enumerate(col_spans):
            marks = [(r - r0, c - c0, grid[r][c])
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != background and grid[r][c] not in sep_colors]
            panels.append((r0, r1, c0, c1, marks))

    # The panel with the most marks is the pattern source; stamp its marks
    # at matching relative positions in every panel of the same dimensions.
    sr0, sr1, sc0, sc1, motif = max(panels, key=lambda p: len(p[4]))
    ph, pw = sr1 - sr0, sc1 - sc0
    out = [row[:] for row in grid]
    for r0, r1, c0, c1, _ in panels:
        if r1 - r0 == ph and c1 - c0 == pw:
            for dr, dc, value in motif:
                out[r0 + dr][c0 + dc] = value
    return out
